<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('commission-filter-form'),u=document.getElementById('commission-user-filter'),p=document.getElementById('commission-partner-filter'),m=document.getElementById('commission-medicine-filter');u?.addEventListener('change',()=>{if(p)p.value='';f?.submit()});p?.addEventListener('change',()=>f?.submit());m?.addEventListener('change',()=>f?.submit());
 const excelDefinitions=@json(\Modules\Pharma\Services\CommissionExportProfileService::COLUMNS),excelGroups=@json(\Modules\Pharma\Services\CommissionExportProfileService::GROUPS),excelDefaults=@json(\Modules\Pharma\Services\CommissionExportProfileService::defaults()),excelStorage=@json(\Modules\Pharma\Services\CommissionExportProfileService::STORAGE_KEY);
 const excelModal=document.getElementById('commission-excel-config'),excelLibrary=document.getElementById('commission-excel-library'),excelSelected=document.getElementById('commission-excel-selected'),excelPreview=document.getElementById('commission-excel-preview'),excelInspector=document.getElementById('commission-excel-inspector');let excelState={},excelActive=null;
 const clone=v=>JSON.parse(JSON.stringify(v)),readExcel=()=>{try{return Object.assign(clone(excelDefaults),JSON.parse(localStorage.getItem(excelStorage)||'{}'))}catch(e){return clone(excelDefaults)}},letter=n=>{let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s},selectedOrder=()=>excelState.column_order.filter(k=>excelState.selected_columns.includes(k));
 const renderExcel=()=>{const search=(document.getElementById('commission-excel-search')?.value||'').toLowerCase(),group=document.getElementById('commission-excel-group')?.value||'all',selected=new Set(excelState.selected_columns);document.getElementById('commission-excel-field-count').textContent=Object.keys(excelDefinitions).length+' fields';excelLibrary.innerHTML=Object.entries(excelGroups).filter(([g])=>group==='all'||group===g).map(([g,label])=>'<div class="mb-2"><div class="mb-1 rounded-lg bg-slate-50 px-2.5 py-2 text-[10px] font-bold uppercase text-slate-500">'+label+'</div>'+Object.entries(excelDefinitions).filter(([k,d])=>d.group===g&&((excelState.headers[k]||d.label)+' '+k).toLowerCase().includes(search)).map(([k,d])=>'<div class="mb-1 flex items-center gap-2 rounded-lg px-2.5 py-2 hover:bg-slate-50"><button type="button" data-edit="'+k+'" class="min-w-0 flex-1 text-left"><b class="block truncate text-xs">'+(excelState.headers[k]||d.label)+'</b><span class="font-mono text-[9px] text-slate-400">'+k+'</span></button>'+(selected.has(k)?'<span class="rounded-md bg-emerald-50 px-1.5 py-1 text-[9px] font-bold text-emerald-700">Đã chọn</span>':'<button type="button" data-add="'+k+'" class="rounded-lg bg-indigo-50 px-2 py-1 text-[10px] font-bold text-indigo-700">+ Thêm</button>')+'</div>').join('')+'</div>').join('');
 const order=selectedOrder();document.getElementById('commission-excel-selected-count').textContent=order.length+' cột';excelSelected.innerHTML=order.map((k,i)=>'<div class="mb-1 grid grid-cols-[36px_1fr_auto] items-center gap-2 rounded-xl border px-2 py-1.5 '+(excelActive===k?'border-indigo-300 bg-indigo-50':'border-slate-200')+'"><span class="grid h-8 place-items-center rounded-lg '+(excelActive===k?'bg-indigo-600 text-white':'bg-slate-100')+' text-[10px] font-extrabold">'+letter(i+1)+'</span><button type="button" data-edit="'+k+'" class="min-w-0 text-left"><b class="block truncate text-xs">'+excelState.headers[k]+'</b><span class="text-[9px] text-slate-400">'+excelState.widths[k]+' px</span></button><div class="flex gap-1"><button data-move="'+k+'" data-offset="-1" class="h-7 w-7 rounded-lg border">↑</button><button data-move="'+k+'" data-offset="1" class="h-7 w-7 rounded-lg border">↓</button><button data-remove="'+k+'" class="h-7 w-7 rounded-lg border border-rose-100 text-rose-500">×</button></div></div>').join('')||'<p class="p-10 text-center text-xs text-slate-400">Chưa chọn cột để xuất.</p>';excelPreview.innerHTML=order.map((k,i)=>'<div class="shrink-0 border-r p-2" style="width:'+Math.max(72,Math.min(210,excelState.widths[k]))+'px"><b class="text-[9px] text-indigo-600">'+letter(i+1)+'</b><p class="truncate text-[10px] font-bold">'+excelState.headers[k]+'</p></div>').join('');document.getElementById('commission-excel-footer').innerHTML='<b>Cấu hình Excel hoa hồng</b> · '+order.length+' cột được chọn';renderInspector()};
 const renderInspector=()=>{if(!excelActive||!excelDefinitions[excelActive]){excelInspector.innerHTML='<p class="text-xs text-slate-400">Chọn một cột để thiết lập.</p>';return}const d=excelDefinitions[excelActive];document.getElementById('commission-excel-inspector-title').textContent=d.label;document.getElementById('commission-excel-inspector-key').textContent=excelActive;excelInspector.innerHTML='<label class="block text-xs font-bold">Tiêu đề Excel<input data-prop="header" value="'+excelState.headers[excelActive]+'" class="mt-1 h-10 w-full rounded-xl border px-3"></label><label class="block text-xs font-bold">Kiểu dữ liệu<select data-prop="data_type" class="mt-1 h-10 w-full rounded-xl border px-3"><option value="auto">Tự động</option><option value="string">Văn bản</option><option value="number">Số</option><option value="date">Ngày</option></select></label><div class="grid grid-cols-2 gap-2 border-t pt-3"><label class="text-xs font-bold">Số lẻ<input data-prop="decimals" type="number" min="0" max="6" value="'+excelState.decimals[excelActive]+'" class="mt-1 h-10 w-full rounded-xl border px-3"></label><label class="text-xs font-bold">Căn<select data-prop="alignment" class="mt-1 h-10 w-full rounded-xl border px-3"><option value="left">Trái</option><option value="center">Giữa</option><option value="right">Phải</option></select></label></div><section class="border-t pt-3"><label class="flex items-center justify-between text-xs font-bold"><span>Auto độ rộng</span><input data-prop="auto_width" type="checkbox" '+((excelState.auto_widths?.[excelActive]??true)?'checked':'')+' class="h-4 w-4"></label><p class="mt-1 text-[9px] text-slate-400">Bật: Excel tự tính. Tắt: nhập độ rộng 40–400 px.</p><label class="mt-3 block text-xs font-bold">Độ rộng <span class="float-right text-[9px] text-slate-400">40–400 px</span><input data-prop="width" type="number" min="40" max="400" value="'+excelState.widths[excelActive]+'" '+((excelState.auto_widths?.[excelActive]??true)?'disabled':'')+' class="mt-1 h-10 w-full rounded-xl border px-3 disabled:bg-slate-100 disabled:text-slate-400"></label><label class="mt-3 flex items-center justify-between text-xs font-bold"><span>Wrap Text</span><input data-prop="wrap_text" type="checkbox" '+((excelState.wrap_texts?.[excelActive]??true)?'checked':'')+' class="h-4 w-4"></label></section>';excelInspector.querySelector('[data-prop="data_type"]').value=excelState.data_types[excelActive];excelInspector.querySelector('[data-prop="alignment"]').value=excelState.alignments[excelActive]};
 const saveInspector=()=>{if(!excelActive)return;excelInspector.querySelectorAll('[data-prop]').forEach(el=>{const p=el.dataset.prop,v=el.value;if(p==='header')excelState.headers[excelActive]=v.trim()||excelDefinitions[excelActive].label;if(p==='data_type')excelState.data_types[excelActive]=v;if(p==='alignment')excelState.alignments[excelActive]=v;if(p==='decimals')excelState.decimals[excelActive]=Math.max(0,Math.min(6,Number(v)||0));if(p==='width')excelState.widths[excelActive]=Math.max(40,Math.min(400,Number(v)||excelDefinitions[excelActive].width));if(p==='auto_width'){excelState.auto_widths=excelState.auto_widths||{};excelState.auto_widths[excelActive]=el.checked}if(p==='wrap_text'){excelState.wrap_texts=excelState.wrap_texts||{};excelState.wrap_texts[excelActive]=el.checked}})};
 const openExcel=()=>{excelState=readExcel();excelActive=selectedOrder()[0]||excelState.column_order[0];renderExcel();excelModal.classList.remove('hidden')},closeExcel=()=>excelModal.classList.add('hidden');
 document.getElementById('commission-excel-group').innerHTML='<option value="all">Tất cả nhóm</option>'+Object.entries(excelGroups).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('');document.getElementById('commission-excel-config-open')?.addEventListener('click',openExcel);document.getElementById('commission-excel-config-close')?.addEventListener('click',closeExcel);document.getElementById('commission-excel-search')?.addEventListener('input',renderExcel);document.getElementById('commission-excel-group')?.addEventListener('change',renderExcel);
 excelModal?.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.edit){saveInspector();excelActive=t.dataset.edit;renderExcel()}if(t.dataset.add){saveInspector();if(!excelState.selected_columns.includes(t.dataset.add))excelState.selected_columns.push(t.dataset.add);excelActive=t.dataset.add;renderExcel()}if(t.dataset.remove){saveInspector();excelState.selected_columns=excelState.selected_columns.filter(k=>k!==t.dataset.remove);excelActive=selectedOrder()[0]||null;renderExcel()}if(t.dataset.move){saveInspector();const order=selectedOrder(),i=order.indexOf(t.dataset.move),j=Math.max(0,Math.min(order.length-1,i+Number(t.dataset.offset)));if(i!==j){order.splice(j,0,order.splice(i,1)[0]);excelState.column_order=[...order,...excelState.column_order.filter(k=>!order.includes(k))]}excelActive=t.dataset.move;renderExcel()}});
 document.getElementById('commission-excel-reset-order')?.addEventListener('click',()=>{saveInspector();const canonical=Object.keys(excelDefinitions),sel=new Set(excelState.selected_columns);excelState.column_order=[...canonical.filter(k=>sel.has(k)),...canonical.filter(k=>!sel.has(k))];renderExcel()});document.getElementById('commission-excel-clear')?.addEventListener('click',()=>{excelState.selected_columns=[];excelActive=null;renderExcel()});
 excelInspector?.addEventListener('change',()=>{saveInspector();renderExcel()});document.getElementById('commission-excel-config-save')?.addEventListener('click',()=>{saveInspector();if(!selectedOrder().length)return alert('Cần chọn ít nhất một cột.');localStorage.setItem(excelStorage,JSON.stringify(excelState));applyExcelToSelected();closeExcel()});
 const excelParam=()=>JSON.stringify(readExcel()),applyExcelToSelected=()=>{const form=document.getElementById('commission-selected-export');form?.querySelectorAll('[data-excel-config]').forEach(x=>x.remove());const i=document.createElement('input');i.type='hidden';i.name='excel_profile';i.value=excelParam();i.dataset.excelConfig='1';form?.appendChild(i)};
 document.getElementById('commission-filter-export')?.addEventListener('click',e=>{e.preventDefault();const url=new URL(e.currentTarget.href,window.location.origin);url.searchParams.set('excel_profile',excelParam());window.location.href=url.toString()});document.getElementById('commission-selected-export')?.addEventListener('submit',applyExcelToSelected);applyExcelToSelected();
 const all=document.getElementById('commission-select-all'),boxes=[...document.querySelectorAll('.commission-row-checkbox')],toolbar=document.getElementById('commission-selection-toolbar'),count=document.getElementById('commission-selected-count'),inputs=document.getElementById('commission-selected-inputs');
 const sync=()=>{const selected=boxes.filter(x=>x.checked);if(count)count.textContent=selected.length;if(toolbar){toolbar.classList.toggle('hidden',selected.length===0);toolbar.classList.toggle('flex',selected.length>0)}if(all){all.checked=boxes.length>0&&selected.length===boxes.length;all.indeterminate=selected.length>0&&selected.length<boxes.length}if(inputs)inputs.innerHTML=selected.map(x=>'<input type="hidden" name="ids[]" value="'+x.value+'">').join('')};
 all?.addEventListener('change',()=>{boxes.forEach(x=>x.checked=all.checked);sync()});boxes.forEach(x=>x.addEventListener('change',sync));document.getElementById('commission-clear-selection')?.addEventListener('click',()=>{boxes.forEach(x=>x.checked=false);sync()});sync();
})</script>
@endsection
